def prime_factors(num):
    factors = []
    i = 2
    while i * i <= num:
        if num % i:
            i += 1
        else:
            num //= i
            factors.append(i)
    if num > 1:
        factors.append(num)
    return factors

def fft_factorize(n):
    result = prime_factors(n)
    return json.dumps({"factors": result, "num_of_factors": len(result)})

