def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_mat = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix_set(gsl_mat.matrix, i, j, float(np_array[i, j]))
    return gsl_mat

def gsl_matrix_to_numpy(gsl_matrix):
    rows, cols = gsl_matrix_size(gsl_matrix)
    np_array = np.empty((rows, cols), dtype=np.float64)
    for i in range(rows):
        for j in range(cols):
            np_array[i, j] = gsl_matrix_get(gsl_matrix, i, j)
    return np_array

