gsl_linalg_complex_QR_decomp_r.argtypes = [gsl_matrix_complex_ptr, ctypes.POINTER(ctypes.c_double), gsl_matrix_complex_ptr]
    gsl_linalg_complex_QR_decomp_r.restype = ctypes.c_int

    status = gsl_linalg_complex_QR_decomp_r(matrix_A_data, None, matrix_A_data)
    if status != 0:
        return status  # Error: QR decomposition failed

    for i in range(nrows_A):
        for j in range(ncols_A):
            A[i, j] = matrix_A_data[i * ncols_A + j]
