class gsl_permutation(ctypes.Structure):
    _fields_ = ["data", "size", "alloc"]

class gsl_vector(ctypes.Structure):
    _fields_ = ["data", "size", "stride", "block", "owner"]

def permute_vector(permutation, vector):
    if len(permutation) != len(vector):
        raise ValueError("Permutation and vector lengths must be equal")

    perm = gsl_permutation()
    vec = gsl_vector((ctypes.c_double * len(vector))(*vector), len(vector), 1)

    result = gsl.gsl_permutation_init(ctypes.byref(perm), len(permutation))
    if result != GSL_SUCCESS:
        raise RuntimeError("Failed to initialize permutation")

    for i, p in enumerate(permutation):
        perm.data[i] = p

    result = gsl.permute_vector(ctypes.byref(perm), ctypes.byref(vec))
    if result != GSL_SUCCESS:
        raise RuntimeError("Failed to permute vector")

    return list(vec.data[:])

