                self.data[i * self.cols + j] = ctypes.c_double(matrix[i][j])

    def find_minmax_indices(self):
        min_index = ctypes.c_int(0)
        max_index = ctypes.c_int(0)
        gsl.gsl_matrix_minmax_index.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
        gsl.gsl_matrix_minmax_index.restype = None
        gsl.gsl_matrix_minmax_index(self.data, self.rows, self.cols, ctypes.byref(min_index), ctypes.byref(max_index))
        return (min_index.value // self.cols, min_index.value % self.cols, max_index.value // self.cols, max_index.value % self.cols)

def find_indices(matrix):
    gsl_mat = GSLMatrix(matrix)
    return gsl_mat.find_minmax_indices()
