#include <gsl/gsl_wavelet.h>
#include <gsl/gsl_vector.h>

int main() {
    FILE *file = fopen("data.txt", "r");
    if (!file) return 1;

    gsl_vector *original = gsl_vector_alloc(256);
    for (size_t i = 0; i < 256; ++i) {
        double value;
        fscanf(file, "%lf", &value);
        gsl_vector_set(original, i, value);
    }

    gsl_wavelet *wavelet = gsl_wavelet_alloc(gsl_wavelet_daubechies4);
    gsl_wavelet_workspace *workspace = gsl_wavelet_workspace_alloc(256);

    gsl_vector *transformed = gsl_vector_alloc(256);
    gsl_wavelet_transform(wavelet, original->data, 1, original->size, workspace);

    for (size_t i = 0; i < 32; ++i) {
        gsl_vector_set(transformed, i, 0.0);
    }

    gsl_wavelet_inverse(wavelet, transformed->data, 1, transformed->size, workspace);

    printf("Original: Transformed:\n");
    for (size_t i = 0; i < 256; ++i) {
        printf("%f: %f\n", gsl_vector_get(original, i), gsl_vector_get(transformed, i));
    }

    fclose(file);
    gsl_vector_free(original);
    gsl_vector_free(transformed);
    gsl_wavelet_workspace_free(workspace);
    gsl_wavelet_free(wavelet);

    return 0;
}

