        for i in range(self.n):
            value = gsl.gsl_vector_get(self.vector, i)
            new_value = value * factor
            gsl.gsl_vector_set(self.vector, i, new_value)

    def get_values(self):
        values = [0.0] * self.n
        for i in range(self.n):
            values[i] = gsl.gsl_vector_get(self.vector, i)
        return values

