def numpy_to_gsl_matrix(matrix):
    rows, cols = matrix.shape
    gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix.data[i * cols + j] = matrix[i, j]
    return gsl_matrix

def numpy_to_gsl_vector(vector):
    size = vector.size
    gsl_vector = gsl.gsl_vector_alloc(size)
    for i in range(size):
        gsl_vector.data[i] = vector[i]
    return gsl_vector

def qr_ud_decomp(U, D, Y, T):
    U_gsl = numpy_to_gsl_matrix(U)
    D_gsl = numpy_to_gsl_matrix(D)
    Y_gsl = numpy_to_gsl_matrix(Y)
    T_gsl = numpy_to_gsl_matrix(T)

    gsl.gsl_linalg_QR_UD_decomp(U_gsl, D_gsl, Y_gsl, T_gsl)

    for i in range(U.shape[0]):
        for j in range(U.shape[1]):
