from typing import List, Tuple, Optional

def load_gsl_libraries() -> None:
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")


class GSLMatrix:
    def __init__(self, data: List[List[complex]]):
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0
        self.data = data

    @staticmethod
    def list_to_gsl_matrix(matrix: List[List[complex]]) -> Optional[int]:
        rows = len(matrix)
        cols = len(matrix[0]) if rows > 0 else 0
        gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
        if gsl_matrix is None:
            return -1
        for i in range(rows):
            for j in range(cols):
                real = matrix[i][j].real
                imag = matrix[i][j].imag
                gsl_matrix.data[i * gsl_matrix.tda + j] = real + imag * 1j
        return gsl_matrix

    @staticmethod
def add_matrices(matrix_a: GSLMatrix, matrix_b: GSLMatrix) -> Optional[GSLMatrix]:
        if not (matrix_a.rows == matrix_b.rows and matrix_a.cols == matrix_b.cols):
            return None
        result = gsl.gsl_matrix_add(matrix_a.list_to_gsl_matrix(matrix_a.data), matrix_b.list_to_gsl_matrix(matrix_b.data))
        if result != 0:
            return None
        rows = matrix_a.rows
        cols = matrix_a.cols
        result_data = [[complex(0, 0)] * cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                real = result.data[i * result.tda + j].real
                imag = result.data[i * result.tda + j].imag
                result_data[i][j] = complex(real, imag)
        return GSLMatrix(result_data)

