class gsl_complex(ctypes.Structure):
    _fields_ = [(\"data\", ctypes.c_double * 2)]

class gsl_matrix_complex(ctypes.Structure):
    _fields_ = [
        ("data", ctypes.POINTER(gsl_complex)),
        ("size1", ctypes.c_size_t),
        ("tda", ctypes.c_size_t)
    ]

def call_gsl_linalg_complex_tri_LHL(matrix):
    n = len(matrix)
    data = (gsl_complex * n * n)()
    for i in range(n):
        for j in range(n):
            data[i * n + j].data[0] = matrix[i][j][0]
            data[i * n + j].data[1] = matrix[i][j][1]

    gsl_matrix_complex m = gsl_matrix_complex(
        ctypes.pointer(data),
        n,
        n
    )

    result = gsl.gsl_linalg_complex_tri_LHL(ctypes.byref(m))

    for i in range(n):
        for j in range(n):
            matrix[i][j] = (m.data[i * n + j].data[0], m.data[i * n + j].data[1])

    return result, matrix

