cdef class GSLVector:
    cdef void* vec

    def __init__(self, size):
        self.vec = gsl.gsl_vector_alloc(size)

    def __getitem__(self, index):
        return gsl.gsl_vector_get(self.vec, index)

    def __setitem__(self, index, value):
        gsl.gsl_vector_set(self.vec, index, value)

    def __del__(self):
        gsl.gsl_vector_free(self.vec)

ctypes.CFUNCTYPE(None, ctypes.POINTER(GSLVector))(
gsl.gsl_linalg_householder_transform,
[("input_vector", ctypes.POINTER(GSLVector))]
)(gslcblas, gsl)

def householder_transform(input_vector):
    vec = GSLVector(len(input_vector))
    for i in range(len(input_vector)):
        vec[i] = input_vector[i]

    tau = gsl.gsl_linalg_householder_transform(vec.vec)

    result_vector = [vec[i] for i in range(len(input_vector))]
    return tau, result_vector

