class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.matrix, i, j, data[i][j])

    def retrieve_gsl_matrix(self):
        result = [[0.0] * self.cols for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(self.cols):
                result[i][j] = gsl.gsl_matrix_get(self.matrix, i, j)
        return result

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

