gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))(*sum(data, []))
        self.matrix = gsl.gsl_matrix_calloc(self.rows, self.cols)
        gsl.set_data_pointer(self.matrix, ctypes.byref(self.data), self.rows * self.cols)

    def __del__(self):
        gsl.free_gsl_matrix(self.matrix)

def create_gsl_matrix(data):
    return GSLMatrix(data)

def retrieve_gsl_matrix(matrix):
    return [[matrix.data[i*matrix.cols + j] for j in range(matrix.cols)] for i in range(matrix.rows)]

# Example usage
