import ctypes
import numpy as np
def load_gsl_linalg_functions():
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def matrix_to_gsl(matrix):
        M, N = len(matrix), len(matrix[0])
        return gsl_matrix(M, N, np.array(matrix).ctypes.data_as(ctypes.POINTER(ctypes.c_double)))

    def vector_to_gsl(vector):
        N = len(vector)
        return gsl_vector(N, np.array(vector).ctypes.data_as(ctypes.POINTER(ctypes.c_double)))

    def gsl_matrix_to_list(matrix):
        M, N = matrix.size1, matrix.size2
        data = np.ctypeslib.as_array(matrix.data, shape=(M * N,))
        return data.reshape(M, N).tolist()

    def gsl_vector_to_list(vector):
        N = vector.size
        data = np.ctypeslib.as_array(vector.data, shape=(N,))
        return data.tolist()

    def ql_decomposition_and_unpack(A, tau):
        A_gsl = matrix_to_gsl(A)
        tau_gsl = vector_to_gsl(tau)
        gsl.gsl_linalg_QL_decomp.restype = ctypes.c_int
        gsl.gsl_linalg_QL_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector)]
        result = gsl.gsl_linalg_QL_decomp(A_gsl, tau_gsl)
        if result != 0:
            raise Exception(f"GSL error {result}")

        Q_gsl = gsl_matrix(A_gsl.size1, A_gsl.size1)
        L_gsl = gsl_matrix(A_gsl.size1, A_gsl.size2)
        gsl.gsl_linalg_QL_unpack.restype = None
        gsl.gsl_linalg_QL_unpack.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix)]
        gsl.gsl_linalg_QL_unpack(A_gsl, tau_gsl, Q_gsl, L_gsl)

        Q = gsl_matrix_to_list(Q_gsl)
        L = gsl_matrix_to_list(L_gsl)

        return Q, L

    return matrix_to_gsl, vector_to_gsl, gsl_matrix_to_list, gsl_vector_to_list, ql_decomposition_and_unpack

def solve(A, tau):
    matrix_to_gsl, vector_to_gsl, gsl_matrix_to_list, gsl_vector_to_list, ql_decomposition_and_unpack = load_gsl_linalg_functions()
    Q, L = ql_decomposition_and_unpack(A, tau)
    return Q, L

