import ctypes

def cblas_ddot(vector_x, vector_y):
    if len(vector_x) != len(vector_y):
        raise ValueError('Vectors must be of the same length')

    n = len(vector_x)
    gslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so', mode=ctypes.RTLD_GLOBAL)

    cblas_ddot_wrapper = gslcblas.cblas_ddot
    cblas_ddot_wrapper.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
    cblas_ddot_wrapper.restype = ctypes.c_double

    x_array = (ctypes.c_double * n)(*vector_x)
    y_array = (ctypes.c_double * n)(*vector_y)

    return cblas_ddot_wrapper(n, x_array, 1, y_array, 1)

